require_once __DIR__ . '/includes/auth.php';requireLogin();$pdo=db();$uid=userId();$pageTitle='Tagihan';$activePage='tagihan.php';
$pdo->prepare('UPDATE bills SET status="Terlambat" WHERE user_id=? AND status="Belum Dibayar" AND due_date<CURDATE()')->execute([$uid]);
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';if($action==='delete'){$st=$pdo->prepare('DELETE FROM bills WHERE id=? AND user_id=?');$st->execute([(int)$_POST['id'],$uid]);flash('success','Tagihan berhasil dihapus.');redirect('tagihan.php');}if($action==='toggle'){$id=(int)$_POST['id'];$status=$_POST['status']==='Sudah Dibayar'?'Sudah Dibayar':'Belum Dibayar';$st=$pdo->prepare('UPDATE bills SET status=? WHERE id=? AND user_id=?');$st->execute([$status,$id,$uid]);flash('success','Status tagihan diperbarui.');redirect('tagihan.php');}if($action==='save'){$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);$amount=parseAmount($_POST['amount']??0);$due=(string)$_POST['due_date'];$category=trim((string)$_POST['category']);$recurring=!empty($_POST['recurring'])?1:0;$desc=trim((string)$_POST['description']);if($name===''||$amount<=0||!validDate($due)||$category===''){flash('error','Lengkapi nama, nominal, tanggal, dan kategori tagihan.');redirect('tagihan.php?action='.($id?'edit&id='.$id:'add'));}if($id){$st=$pdo->prepare('UPDATE bills SET name=?,amount=?,due_date=?,category=?,recurring=?,description=? WHERE id=? AND user_id=?');$st->execute([$name,$amount,$due,$category,$recurring,$desc,$id,$uid]);}else{$st=$pdo->prepare('INSERT INTO bills(user_id,name,amount,due_date,category,recurring,status,description) VALUES(?,?,?,?,?,?,"Belum Dibayar",?)');$st->execute([$uid,$name,$amount,$due,$category,$recurring,$desc]);}flash('success','Tagihan berhasil disimpan.');redirect('tagihan.php');}}
$q=trim((string)($_GET['q']??''));$where='user_id=?';$params=[$uid];if($q!==''){$where.=' AND (name LIKE ? OR category LIKE ?)';$params[]="%{$q}%";$params[]="%{$q}%";}$st=$pdo->prepare("SELECT * FROM bills WHERE {$where} ORDER BY status='Sudah Dibayar',due_date");$st->execute($params);$rows=$st->fetchAll();$edit=null;if(($_GET['action']??'')==='edit'){$st=$pdo->prepare('SELECT * FROM bills WHERE id=? AND user_id=?');$st->execute([(int)$_GET['id'],$uid]);$edit=$st->fetch()?:null;}if(($_GET['action']??'')==='add')$edit=['id'=>0,'name'=>'','amount'=>'','due_date'=>date('Y-m-d',strtotime('+7 days')),'category'=>'Internet','recurring'=>0,'description'=>''];$cats=['Listrik','Internet','Sewa','Cicilan','Subscription','Pendidikan','Kesehatan','Lainnya'];$user=currentUser($pdo);require __DIR__.'/includes/header.php';
